  //     minAppVersion,
  //     undefined, // releaseNotes
  //     uploadResult.storagePath,
  //     uploadResult.bucket,
  //     uploadResult.tempPath,
  //     uploadResult.fileSizeBytes,
  //     uploadResult.checksumSha256,
  //   );
  // }

  /**
   * Retrieves all versions of a plugin.
   */
  async getPluginVersions(packageId: string): Promise<PluginVersionResponse[]> {
    this.logger.debug(`Fetching versions for plugin ${packageId}`);

    const plugin = await this.pluginsRepository.findByPackageId(packageId);
    if (!plugin) {
      throw new ResourceNotFoundException('Plugin', 'packageId', packageId);
    }

    const versions = await this.versionsRepository.findByPluginIdOrderByCreatedAtDesc(plugin.id);

    return versions.map((v) => this.toPluginVersionResponse(v));
  }

  /**
   * Retrieves a specific version by ID.
   */
  async getVersionById(versionId: string): Promise<PluginVersionResponse> {
    this.logger.debug(`Fetching version ${versionId}`);

    const version = await this.versionsRepository.findById(versionId);
    if (!version) {
      throw new ResourceNotFoundException('PluginVersion', 'id', versionId);
    }

    return this.toPluginVersionResponse(version);
  }

  /**
   * Increments the download count for a version.
   */
  async incrementDownloadCount(versionId: string): Promise<void> {
    await this.versionsRepository.incrementDownloadCount(versionId);
    this.logger.debug(`Incremented download count for version ${versionId}`);
  }

  /**
   * Deletes a plugin and all its associated versions with full storage cleanup.
   * This is a hard delete operation that removes:
   * - All plugin version artifacts from storage
   * - Plugin icon from storage
   * - All plugin version records from database
   * - The plugin record from database
   */
  async deletePlugin(packageId: string): Promise<void> {
    this.logger.log(`Deleting plugin ${packageId}`);

    // Get the plugin
    const plugin = await this.pluginsRepository.findByPackageId(packageId);
    if (!plugin) {
      throw new ResourceNotFoundException('Plugin', 'packageId', packageId);
    }

    // Get all versions for storage cleanup
    const versions = await this.versionsRepository.findByPluginIdOrderByCreatedAtDesc(plugin.id);

    // Delete all version artifacts from storage
    for (const version of versions) {
      // Delete permanent storage files
      if (version.storagePath && version.storageBucket) {
        try {
          await this.storageService.deleteArtifact(version.storagePath, version.storageBucket);
          this.logger.log(`Deleted artifact from storage: ${version.storagePath}`);
        } catch (error) {
          this.logger.error(`Failed to delete artifact ${version.storagePath}: ${error.message}`);
          // Continue with deletion even if storage cleanup fails
        }
      }

      // Delete temporary storage files
      if (version.tempStoragePath) {
        try {
          await this.storageService.deleteArtifact(version.tempStoragePath, 'temp_uploads');
          this.logger.log(`Deleted temp artifact from storage: ${version.tempStoragePath}`);
        } catch (error) {
          this.logger.error(`Failed to delete temp artifact ${version.tempStoragePath}: ${error.message}`);
          // Continue with deletion even if storage cleanup fails
        }
      }
    }

    // Delete plugin icon from storage
    if (plugin.iconKey) {
      try {
        await this.storageService.deleteArtifact(plugin.iconKey, 'icons');
        this.logger.log(`Deleted icon from storage: ${plugin.iconKey}`);
      } catch (error) {
        this.logger.error(`Failed to delete icon ${plugin.iconKey}: ${error.message}`);
        // Continue with deletion even if storage cleanup fails
      }
    }

    // Delete all version records from database
    await this.versionsRepository.deleteByPluginId(plugin.id);

    // Delete the plugin record from database
    await this.pluginsRepository.delete(plugin.id);

    this.logger.log(`Successfully deleted plugin ${packageId} and all associated data`);
  }

  /**
   * Retrieves statistics about a plugin.
   */
  async getPluginStatistics(packageId: string): Promise<PluginStatisticsResponse> {
    this.logger.debug(`Fetching statistics for plugin ${packageId}`);

    const plugin = await this.pluginsRepository.findByPackageId(packageId);
    if (!plugin) {
      throw new ResourceNotFoundException('Plugin', 'packageId', packageId);
    }

    const allVersions = await this.versionsRepository.findByPluginIdOrderByCreatedAtDesc(plugin.id);
    const totalDownloads = allVersions.reduce((sum, v) => sum + v.downloadCount, 0);

    const publishedVersions = await this.versionsRepository.countByPluginIdAndStatus(
      plugin.id,
      'PUBLISHED' as any,
    );

    return new PluginStatisticsResponse(
      plugin.packageId,
      plugin.name,
      plugin.status,
      allVersions.length,
      publishedVersions,
      totalDownloads,
      plugin.createdAt,
      plugin.updatedAt,
    );
  }

  // ===== Private helper methods =====

  private toPluginResponse(plugin: Plugin): PluginResponse {
    return new PluginResponse(
      plugin.id,
      plugin.packageId,
      plugin.name,
      plugin.description || null,
      plugin.author,
      plugin.iconKey || null,
      plugin.status,
      plugin.latestVersionId || null,
      plugin.category || null,
      plugin.tags || null,
      plugin.sourceUrl || null,
      plugin.createdAt,
      plugin.updatedAt,
    );
  }

  private async toPluginDetailResponse(
    plugin: Plugin,
    version: PluginVersion,
  ): Promise<PluginDetailResponse> {
    // Generate signed URL for download
    let downloadUrl: string | null = null;
    let expiresAt: number | null = null;



    let storagePath = version.storagePath;
    let storageBucket = version.storageBucket;

     if(version.status === PluginStatus.SUBMITTED.toString()) {
      storagePath = version.tempStoragePath;
    }

    if (storagePath && storageBucket) {
      try {
        const signedUrl = await this.storageService.getSignedUrl(storagePath, storageBucket);
        downloadUrl = signedUrl.signedUrl;
        expiresAt = signedUrl.expiresAt;
      } catch (error) {
        this.logger.warn(`Failed to generate signed URL for version ${version.id}: ${error.message}`);
      }
    }

    return new PluginDetailResponse(
      // Plugin metadata
      plugin.id,
      plugin.packageId,
      plugin.name,
      plugin.description || null,
      plugin.author,
      plugin.iconKey || null,
      plugin.status,
      plugin.category || null,
      plugin.tags || null,
      plugin.sourceUrl || null,
      plugin.createdAt,
      // Version details
      version.id,
      version.version,
      version.manifest,
      version.minAppVersion,
      version.releaseNotes || null,
      version.createdAt,
      version.downloadCount,
      // Download information
      downloadUrl,
      expiresAt,
      version.fileSizeBytes || null,
      version.checksumSha256 || null,
      storageBucket || null,
      storagePath || null,
    );
  }

  private toPluginVersionResponse(version: PluginVersion): PluginVersionResponse {
    return new PluginVersionResponse(
      version.id,
      version.pluginId,
      version.version,
      version.manifest,
      version.minAppVersion,
      version.releaseNotes || null,
      version.status,
      version.rejectionReason || null,
      version.reviewedBy || null,
      version.createdAt,
      version.reviewedAt || null,
      version.publishedAt || null,
      version.downloadCount,
      version.isFlagged,
      // Storage information
      version.storagePath || null,
      version.storageBucket || null,
      version.fileSizeBytes || null,
      version.checksumSha256 || null,
    );
  }
}

